Algoritmo Dado
  Definir tirada Como Entero;
  Definir intentos Como Entero <- 0;
  Repetir
    tirada <- Azar(6) + 1;
    intentos <- intentos + 1;
  Hasta Que tirada = 6
  Escribir "Salió el 6 en el intento ", intentos;
FinAlgoritmo

Algoritmo UnaVez
  Definir n Como Entero <- 10;
  Repetir
    Escribir "Vuelta con n = ", n;
    n <- n + 1;
  Hasta Que n > 5
FinAlgoritmo

Algoritmo RepetirNumero
  Definir n Como Entero <- 3;
  Repetir
    n <- n - 1;
  Hasta Que n
FinAlgoritmo
